calc.script:
const portfolio={"bratislava|1": {"count": 66, "adr": 68.57}, "kosice|1": {"count": 15, "adr": 45.71}, "bratislava|3": {"count": 4, "adr": 153.65}, "bratislava|2": {"count": 28, "adr": 101.43}, "kosice|2": {"count": 5, "adr": 83.5}};
const stayStats={"bratislava|1": {"guests": 1.73, "stay": 3.77, "n": 1126, "listings": 66}, "kosice|1": {"guests": 1.43, "stay": 4.46, "n": 235, "listings": 15}, "bratislava|3": {"guests": 5.03, "stay": 2.91, "n": 79, "listings": 4}, "bratislava|2": {"guests": 3.3, "stay": 3.64, "n": 472, "listings": 28}, "kosice|2": {"guests": 3.08, "stay": 4.56, "n": 62, "listings": 5}};
const defs=[['adr',"Precio por noche ocupada",'€',0,500,.01,100,"Valor inicial basado en la cartera; al modificarlo, se utiliza su supuesto."],['occupancy',"Ocupación de noches disponibles",'%',0,100,1,65,"El 65% inicial es una suposición ilustrativa, no una ocupación medida."],['own',"Noches de uso propio / noches bloqueadas","noches",0,30,1,0,"Reducen el número de noches ofertadas en alquiler."]];
const costs=[['portal',"Tarifas del portal",'%',0,30,.5,0,"Valor inicial: 0 %, sin especificar. Introduzca solo las comisiones que aún no se hayan deducido."],['clean',"Precio por limpieza",'€',0,150,.5,32.5,"Apartamento más pequeño: 30-35 €, más grande: 40-50 €. Una suposición LIVE-IN, no un promedio de las facturas."],['cleanPaid',"Importe de limpieza pagado por el huésped por estancia",'€',0,150,.5,0,"Valor inicial: 0 €. Introduzca el importe neto solo si aún no está incluido en los ingresos por noche; de lo contrario, se contabilizaría dos veces."],['avgGuests',"Número medio de huéspedes por reserva","huéspedes",1,30,.01,2,"Media de las reservas de apartamentos comparables, limitada a la capacidad de su apartamento. Puede modificarla. No afecta al precio por noche ni al precio de la limpieza."],['stay',"Duración media de la estancia","noches",1,365,.01,3,"Media de las reservas históricas, con una limpieza después de cada estancia. Puede modificarla."],['fixed',"Suministros y otros gastos mensuales",'€',0,2000,10,0,"Aún sin especificar. Incluya también internet, seguro y una reserva para reparaciones."]];
let initial=null,snapshot=null,initialSize="small";
const el=id=>document.getElementById(id),fmt=v=>new Intl.NumberFormat("es-ES",{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(v),cent=v=>Math.round((v+Number.EPSILON)*100)/100;
function renderControls(list,target){el(target).innerHTML=list.map(([id,label,unit,min,max,step,val,hint])=>`<div class="control"><label for="${id}">${label} (${unit})<input id="${id}" type="number" min="${min}" max="${max}" step="${step}" value="${val}" required></label><input id="${id}Range" type="range" aria-label="${label}" min="${min}" max="${max}" step="${step}" value="${val}"><small>${hint}</small></div>`).join('');}
renderControls(defs,'controls');renderControls(costs,'costControls');
function values(){return Object.fromEntries([...defs,...costs].map(d=>[d[0],Number(el(d[0]).value)]));}
function calculate(v){const nights=(30-v.own)*v.occupancy/100,gross=cent(nights*v.adr),portal=cent(gross*v.portal/100),income=cent(gross-portal),management=Math.round(Math.round(income*100)*17/100)/100,vat=Math.round(Math.round(income*100)*5/100)/100,bookings=nights/v.stay,guestVisits=bookings*v.avgGuests,cleanGross=cent(bookings*v.clean),cleanRecovery=cent(bookings*v.cleanPaid),clean=cent(cleanGross-cleanRecovery),net=cent(income-management-vat-clean-50-v.fixed);return{nights,bookings,guestVisits,cleanGross,cleanRecovery,gross,portal,income,management,vat,clean,net};}
function update(){if(!initial)return;for(const d of [...defs,...costs]){const field=el(d[0]);if(field.value===''||!Number.isFinite(+field.value)||+field.value<d[3]||+field.value>Number(field.max)){el('print').disabled=true;el('netBar').style.width='0%';el('costBar').style.width='0%';el('net').textContent="Introduzca un valor válido";el('annual').textContent='';el('ledger').textContent="El resultado se restablece después de corregir la entrada.";el('comparison').hidden=true;return;}}
el('print').disabled=false;const v=values(),r=calculate(v);el('net').textContent=fmt(r.net);el('annual').textContent="Escenario de 30 días · incluye la estimación de limpieza";el('ledger').innerHTML=[["Noches ocupadas",r.nights.toLocaleString("es-ES",{maximumFractionDigits:1})+' / '+(30-v.own)],["Ingresos brutos estimados",fmt(r.gross)],["Tarifas del portal",'− '+fmt(r.portal)],["Rental Income estimado",fmt(r.income)],["Gestión · 17 %",'− '+fmt(r.management)],["IVA · 5% según lo especificado",'− '+fmt(r.vat)],["Número estimado de reservas / limpiezas",r.bookings.toLocaleString("es-ES",{maximumFractionDigits:1})],["Huéspedes por reserva",v.avgGuests.toLocaleString("es-ES",{maximumFractionDigits:2})],["Llegadas estimadas de huéspedes por mes",r.guestVisits.toLocaleString("es-ES",{maximumFractionDigits:1})],["Limpieza total",'− '+fmt(r.cleanGross)],["Importes de limpieza pagados por los huéspedes",'+ '+fmt(r.cleanRecovery)],["Guesty / mes",'− 50 €'],["Otros gastos introducidos",'− '+fmt(v.fixed)]].map(x=>`<div class="line"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('');const share=r.gross?Math.min(100,Math.max(0,r.net/r.gross*100)):0;el('netBar').style.width=share+'%';el('costBar').style.width=(100-share)+'%';if(snapshot){el('comparison').hidden=false;el('comparison').textContent="Respecto al escenario guardado: "+(r.net-snapshot.net>=0?'+':'')+fmt(r.net-snapshot.net)+" / mes (antes "+fmt(snapshot.net)+').';}}
for(const d of [...defs,...costs])for(const suffix of ['', 'Range'])el(d[0]+suffix).addEventListener('input',()=>{el(d[0]+(suffix?'':'Range')).value=el(d[0]+suffix).value;update();});
el('profile').addEventListener('submit',e=>{e.preventDefault();if(!el('profile').reportValidity())return;const segment=portfolio[el('city').value+'|'+el('bedrooms').value];if(!segment){el('profileError').textContent="Todavía no disponemos de al menos 3 apartamentos comparables de este tipo. Necesita una evaluación individual; no asignamos un precio automáticamente.";el('adjust').hidden=true;el('numbers').hidden=true;el('empty').hidden=false;initial=null;return;}el('profileError').textContent='';snapshot=null;el('comparison').hidden=true;for(const d of [...defs,...costs]){el(d[0]).value=d[0]==='adr'?segment.adr:d[6];el(d[0]+'Range').value=el(d[0]).value;}const historical=stayStats[el('city').value+'|'+el('bedrooms').value];el('cleanSize').value=(+el('bedrooms').value>=2||+el('area').value>=70)?'large':'small';for(const [id,value] of Object.entries({clean:el('cleanSize').value==='large'?45:32.5,stay:historical?historical.stay:3,avgGuests:Math.min(+el('guests').value,historical?historical.guests:2)})){el(id).value=value;el(id+'Range').value=value;}el('avgGuests').max=el('guests').value;el('avgGuestsRange').max=el('guests').value;initialSize=el('cleanSize').value;initial=values();el('evidence').textContent=`${segment.count} apartamentos comparables por ciudad y número de dormitorios. Precio histórico: ${fmt(segment.adr)}/noche. Perfil: ${el('area').value} m², ${el('guests').value} huéspedes, ${el('location').selectedOptions[0].textContent.toLowerCase()}, ${el('standard').selectedOptions[0].textContent.toLowerCase()} estándar.`;el('evidence').textContent+=historical?` Número de huéspedes y duración de la estancia: ${historical.n} reservas no canceladas en ${historical.listings} apartamentos, con fecha de salida entre julio y septiembre de 2026. Media de huéspedes: ${historical.guests}, estancia ${historical.stay} noches. Son datos de reservas consultados el 12 de octubre de 2026; la realización de las estancias no se ha verificado contablemente. Limitamos la media de huéspedes a la capacidad del apartamento.`:" Utilizamos supuestos ilustrativos para el número de huéspedes y la duración de la estancia.";el('adjust').hidden=false;el('numbers').hidden=false;el('empty').hidden=true;el('numbers').classList.add('fade');update();if(matchMedia('(max-width: 800px)').matches){el('result').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});el('result').focus({preventScroll:true});}});
el('cleanSize').addEventListener('change',()=>{el('clean').value=el('cleanSize').value==='large'?45:32.5;el('cleanRange').value=el('clean').value;update();});
el('reset').addEventListener('click',()=>{if(!initial)return;el('cleanSize').value=initialSize;for(const [id,v]of Object.entries(initial)){el(id).value=v;el(id+'Range').value=v;}update();});el('save').addEventListener('click',()=>{if([...defs,...costs].some(d=>!el(d[0]).checkValidity()))return;snapshot=calculate(values());update();});
for(const id of ['city','bedrooms','location','standard','area','guests'])el(id).addEventListener('input',()=>{if(initial){el('profileError').textContent="El perfil ha cambiado. Haga clic en \"Ver mi escenario\" para restaurar apartamentos y configuraciones comparables.";el('adjust').hidden=true;el('numbers').hidden=true;el('empty').hidden=false;initial=null;}});
